#[derive(Debug, Clone, Copy, PartialEq)]
pub enum ColorMode { Fixed, Cyclic, Reactive }

#[derive(Debug, Clone)]
pub struct ChromaticColor {
    pub hex:     &'static str,
    pub name:    &'static str,
    pub meaning: &'static str,
}

pub const PALETTE: &[ChromaticColor] = &[
    ChromaticColor { hex: "#FF6B9D", name: "Rose",  meaning: "passion" },
    ChromaticColor { hex: "#4ECDC4", name: "Cyan",  meaning: "clarity" },
    ChromaticColor { hex: "#FFE66D", name: "Jaune", meaning: "joy" },
    ChromaticColor { hex: "#95E1D3", name: "Mint",  meaning: "healing" },
    ChromaticColor { hex: "#F38181", name: "Coral", meaning: "tenderness" },
];
